"""Explain memset limits, origin chaining and local-variable origins."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1777': ('칠한 자리에 완료 표시를 붙일 수는 있어도, 사용한 물감이 제대로 준비됐는지에 관한 기록까지 저절로 생기지는 않아요.', 'memset의 실제 채우기와 검사 정보 부족을 구별합니다.', '초기화된 c=23으로 세 바이트를 채우는 그림을 그리고 데이터 23·23·23과 준비됨 검사표를 따로 그리세요.', ['memset은 지정한 바이트 값으로 메모리 범위를 채워요. dst는 채울 곳, c는 채울 값을 정하는 인자, n은 바이트 수예요. c가 준비된 값 23이고 n이 3이면 세 바이트에 각각 23이 들어가요.', '__msan_memset은 먼저 dst 포인터 자체의 검사 정보를 받아 둔 뒤 __memset으로 실제 채우기를 해요. 이후 KMSAN이 꺼졌거나 도구 자신의 처리 중이면 실제 결과를 그대로 반환해요.', '검사도 진행하는 경로는 도구 처리에 들어가 dst 범위를 unpoison해요. unpoison은 shadow 검사표를 준비됨 상태로 바꾸는 말이에요. 이때 checked에는 false를 전달하고, 처리에서 나온 뒤 반환값 검사 정보도 설정해요.', '원문 주석은 이 경로에서 Clang이 c에 관한 검사 정보를 전달하지 않아 c의 shadow로 dst의 shadow를 정할 수 없다고 설명해요. Clang은 프로그램을 기계가 실행할 형태로 바꾸며 검사 코드를 붙이는 컴파일러예요.', '어떤 숫자를 실제로 썼는지와 그 숫자를 만들 때 준비되지 않은 값을 사용했는지는 다른 문제예요. c의 검사표를 받지 못하면 이 함수가 그 정보를 이용해 도착 검사표를 계산할 수 없어요. 앞에서 받은 dst 포인터의 정보가 c의 정보를 대신하지도 않아요.', '도착지를 준비됨으로 표시한다고 잘못된 c 사용을 고쳐 주는 것은 아니에요. 값을 넣지 않은 변수를 읽는 코드를 안전한 예제로 삼지 마세요. 여기서는 확실히 초기화한 c=23으로 데이터 채우기를 이해하고, 누락된 추적 정보의 한계를 따로 살펴요.'], [('왜 이 경로는 c의 shadow로 도착지 shadow를 계산할 수 없나요?', ['dst가 언제나 NULL이기 때문이에요', 'Clang이 이 경로에 c의 검사 정보를 전달하지 않기 때문이에요'], '정답은 두 번째예요. 원문 주석이 그 정보의 부재를 설명해요. 주소가 항상 없다는 뜻이 아니라, 채울 값의 준비 상태를 추적할 정보를 받지 못한다는 뜻이에요.'), ('도착지를 unpoison하면 준비되지 않은 c를 사용해도 항상 안전해지나요?', ['아니요. 검사표 변경은 잘못된 값 사용을 고쳐 주지 않아요', '네. 검사 도구가 모든 잘못된 사용을 없애 줘요'], '정답은 첫 번째예요. 검사 정보의 한계와 프로그램이 지켜야 할 사용 조건은 달라요. 연습에서는 초기화된 값을 사용해야 해요.')]), 'os1778': ('문제가 있는 물건이 누구를 거쳐 왔는지 기록을 잇는다고 생각해 보세요. 기록을 새로 만드는 일도 메모리가 필요할 수 있어 검사 도구의 자기 작업을 구별해야 해요.', '원인 기록 연결 함수의 반환값과 저장·복구 순서를 이해합니다.', '비활성 경로는 0 반환, 정상 경로는 save → 진입 → 원인 연결 → 종료 → restore → 결과 반환으로 그리세요.', ['origin은 준비되지 않은 값의 원인을 찾아갈 기록 번호예요. chain은 이전 기록에 새 기록을 연결하는 사슬을 뜻해요. __msan_chain_origin은 내부 도우미를 불러 이 연결 작업을 요청해요.', '처음에 ret를 0으로 정해요. KMSAN이 꺼져 있거나 도구 자신의 처리 중이면 곧바로 ret를 반환해요. 따라서 이 경로는 입력 origin을 그대로 돌려주는 것이 아니라 0을 돌려줘요.', '계속 진행하면 user_access_save로 사용자 메모리 접근 상태를 저장해요. 이어 enter_runtime으로 KMSAN 자신의 일을 처리 중이라고 표시해요. 원문 주석은 새 원인 기록을 만들 때 메모리를 할당할 수 있다고 설명해요.', '도구의 메모리 할당이 다시 도구의 같은 처리를 끝없이 부르면 곤란해요. 진입 표시는 다른 관련 경로에서 자기 작업을 구별하도록 돕는 장치예요. 이 안에서 kmsan_internal_chain_origin(origin)을 호출하고 그 결과를 ret에 받아요.', '정상적으로 내부 호출이 돌아오면 leave_runtime으로 나오고 user_access_restore로 앞의 상태를 복구해요. 마지막에 내부 도우미의 결과 ret를 반환해요. 예시로 내부 결과가 101이면 반환값도 101이지만, 항상 101이나 새 번호가 나온다는 보장은 아니에요.', '이 바깥 함수에는 결과가 0이면 입력 origin으로 바꾸는 코드가 없어요. 다른 메타데이터 복사 경로에 그런 대체 처리가 있더라도 그 규칙을 여기에 옮겨 생각하면 안 돼요. 어느 함수가 0을 만들고 어느 호출자가 해석하는지 따로 따라가세요.'], [('KMSAN이 꺼져 있을 때 이 함수가 바로 반환하는 값은 무엇인가요?', ['입력 origin을 반드시 그대로 반환해요', '처음 정해 둔 ret 값 0을 반환해요'], '정답은 두 번째예요. ret = 0 다음에 조건에 따른 return ret가 있어요. 이 경로에는 입력 번호를 복사하는 대입이 없어요.'), ('정상 경로에서 사용자 접근 상태는 언제 복구하나요?', ['내부 원인 연결 호출과 leave_runtime 뒤에 복구해요', '저장만 하고 복구하지 않아요'], '정답은 첫 번째예요. save, enter, 내부 호출, leave, restore 순서예요. 반환하기 전에 저장했던 ua_flags를 restore에 전달해요.')]), 'os1779': ('아직 쓰지 않은 메모장에 누가 어디서 만들었는지 꼬리표를 붙여요. 나중에 빈 내용을 읽는 실수를 찾았을 때 시작 지점을 알려 주기 위해서예요.', '지역 변수의 미준비 표시와 네 칸 원인 기록을 이해합니다.', '0번 종류 표식, 1번 설명 주소, 2번 바로 위 복귀 주소, 3번 그 위 복귀 주소 또는 0의 네 칸을 그리세요.', ['지역 변수는 함수 안에서 사용하는 변수예요. __msan_poison_alloca는 함수에 들어갈 때 해당 메모리가 아직 준비되지 않았다는 검사 표시를 만드는 도우미예요. 실제 변수 데이터를 -1로 채우는 함수라고 읽으면 안 돼요.', 'KMSAN이 꺼졌거나 도구 자신의 처리 중이면 끝나요. 그렇지 않으면 접근 상태를 저장하고 unsigned long entries[4]라는 네 칸 배열에 원인 설명에 필요한 정보를 모아요. 칸 번호는 0부터 3까지예요.', '0번에는 KMSAN_ALLOCA_MAGIC_ORIGIN을 넣어요. magic은 여기서 기록 종류를 알아보는 특별한 표식이에요. 1번에는 descr의 주소를 넣어요. descr는 변수 설명을 가리키는 포인터이며 여기서는 설명 문자열 전체를 복사하지 않아요.', '2번에는 __builtin_return_address(0)의 결과를 넣어요. 이는 이 도우미를 부른 쪽으로 돌아갈 코드 위치를 나타내요. 3번에는 설정에 따라 한 단계 더 위의 복귀 주소를 넣거나 0을 넣어요. PC는 이런 코드 위치를 뜻하는 말로 사용돼요.', '기록 저장은 메모리를 할당할 수 있어 enter_runtime과 leave_runtime 사이에서 stack_depot_save를 불러요. 네 칸을 저장하고 받은 handle은 그 기록을 가리키는 번호예요. 네 칸이 있다고 네 개의 별도 원인 번호를 만드는 것은 아니에요.', '그다음 set_shadow_origin에 address, size, -1, handle, checked true를 전달해요. shadow의 바이트를 FF로 만드는 미준비 표시와 원인 번호를 연결하는 요청이에요. 마지막에 접근 상태를 복구해요. 문자열 주소와 복귀 주소를 다루는 조건은 실제 호출 환경이 제공해야 해요.'], [('지역 변수 원인 기록용 entries 배열은 몇 칸인가요?', ['다른 chain 기록과 같으니 세 칸이에요', '종류 표식·설명 주소·복귀 주소 둘을 위한 네 칸이에요'], '정답은 두 번째예요. entries[4]를 선언하고 0~3번을 채워요. 마지막 주소를 얻지 않는 경우에도 네 번째 칸에 0을 넣어요.'), ('이 함수의 set_shadow_origin에 전달하는 checked 값은 무엇인가요?', ['true예요', '어셈블리 출력 처리처럼 항상 false예요'], '정답은 첫 번째예요. 함수 끝 인자에 checked true가 있어요. 다른 도우미의 설정을 이름만 보고 그대로 적용하면 안 돼요.')]), 'os1780': ('누가 누구에게 일을 부탁했는지 한 단계 더 거슬러 보려면 따라갈 표시가 필요해요. 표시가 없는 구성에서는 주소를 지어내는 대신 빈 값으로 남겨요.', '프레임 포인터 설정에 따른 두 번째 복귀 주소 수집을 이해합니다.', 'A가 B를 부르고 B가 이 도우미를 부른 그림을 그려 두 복귀 위치를 표시하세요. 설정이 꺼지면 둘째 칸에 0을 쓰세요.', ['함수가 다른 함수를 부르면 돌아올 위치 같은 실행 정보가 필요해요. 스택 프레임은 각 함수 실행에 관련된 정보를 담는 단위예요. 프레임 포인터는 이런 프레임을 찾아가는 데 쓰이는 기준 주소예요.', '__msan_poison_alloca는 entries[2]에 __builtin_return_address(0)을 넣어요. 이 도우미를 직접 부른 함수 쪽으로 돌아갈 위치예요. 한 단계 더 위의 호출 정보를 얻는 것은 별도의 작업이에요.', 'CONFIG_UNWINDER_FRAME_POINTER가 켜졌는지 확인한 뒤, 켜진 경우 entries[3]에 __builtin_return_address(1)을 넣어요. 0과 1은 주소값 자체가 아니라 얼마나 위의 호출을 볼지 지정하는 단계 번호예요.', '원문 주석은 프레임 포인터가 있으면 전체 호출 경로를 푸는 unwinder를 부르지 않고 둘째 프레임을 빠르게 얻을 수 있다고 설명해요. unwinder는 쌓여 있는 호출 정보를 거슬러 살펴보는 도구예요.', '설정이 꺼져 있으면 else에서 entries[3] = 0을 실행해요. 첫 복귀 주소와 설명 기록까지 모두 지우는 것은 아니에요. 두 번째 주소를 이번 방식으로 수집하지 않았다는 빈 표시를 남기는 것이에요.', '종이에 첫 주소를 0xABC, 둘째를 0xDEF라고 정해 설정별 결과를 비교할 수 있어요. 이는 분기를 이해하기 위한 모델 숫자예요. 실제 스택에서 상위 주소를 읽는 안전성이나 모든 CPU 기종의 호출 추적을 검증한 실험으로 해석하지 마세요.'], [('프레임 포인터 설정이 꺼져 있으면 entries[3]에는 무엇을 넣나요?', ['우연히 남은 임의의 스택 값을 넣어요', '명시적으로 0을 넣어요'], '정답은 두 번째예요. else 분기에 entries[3] = 0이 있어요. 모르는 주소를 추측해서 채우는 코드가 아니에요.'), ('0xABC와 0xDEF 같은 주소를 정한 모델만으로 실제 상위 스택 추적을 검증했다고 할 수 있나요?', ['아니요. 모델은 분기와 칸 구성을 확인하는 예시예요', '네. 모든 기종에서 실제 상위 주소 읽기가 검증돼요'], '정답은 첫 번째예요. 실제 복귀 주소를 얻는 동작과 정해 둔 숫자를 넣는 모델은 달라요. 무엇을 확인했는지 범위를 구분해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_440.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
